function tags(value) { return String(value || '').split(',').map(item => item.trim()).filter(Boolean); }
function statusClass(status) { return String(status || '').toLowerCase(); }
function getExperiment(id) { return state.experiments.find(item => item.id === id); }

function renderJournal() {
  const query = ($('#journal-search')?.value || '').toLowerCase(); const filter = $('#journal-filter')?.value || '';
  const entries = state.journalEntries.filter(entry => { const haystack = [entry.title, entry.purpose, entry.opening, entry.heart, entry.dryDown, ...(entry.tags || []), ...(entry.descriptors || [])].join(' ').toLowerCase(); return haystack.includes(query) && (!filter || filter === (entry.measuredResults ? 'measured' : 'personal')); });
  $('#journal-result-count').textContent = `${entries.length} record${entries.length === 1 ? '' : 's'}`;
  $('#journal-list').innerHTML = entries.length ? entries.map(entry => `<article class="record" data-journal-id="${esc(entry.id)}"><div class="record-top"><div><h3>${esc(entry.title)}</h3><span class="record-date">${formatDate(entry.observedAt)} · ${esc(entry.medium || 'Medium not recorded')}</span></div><div class="record-actions"><button class="icon-button" data-action="duplicate-journal">Duplicate</button><button class="icon-button" data-action="open-journal">Open</button></div></div><p class="record-summary">${esc(entry.overall || entry.opening || entry.personalNotes || 'No sensory summary recorded yet.')}</p><div class="chips">${(entry.descriptors || []).map(item => `<span class="chip">${esc(item)}</span>`).join('')}</div></article>`).join('') : '<div class="empty-state"><strong>No entries match this view.</strong>Record an observation or adjust the search.</div>';
}

function renderExperiments() {
  const query = ($('#experiment-search')?.value || '').toLowerCase(); const status = $('#experiment-status')?.value || '';
  const experiments = state.experiments.filter(item => `${item.title} ${item.experimentId} ${item.objective}`.toLowerCase().includes(query) && (!status || item.status === status));
  $('#experiment-list').innerHTML = experiments.length ? experiments.map(experiment => { const revisions = state.revisions.filter(item => (experiment.formulaRevisionIds || []).includes(item.id)); const batches = state.batches.filter(item => (experiment.batchIds || []).includes(item.id)); return `<article class="experiment-card" data-experiment-id="${esc(experiment.id)}"><div class="experiment-meta"><span>${esc(experiment.experimentId)}</span><span class="status ${statusClass(experiment.status)}">${esc(experiment.status)}</span></div><h3>${esc(experiment.title)}</h3><p>${esc(experiment.objective || 'No objective recorded.')}</p><div class="chips"><span class="chip">${revisions.length} revision${revisions.length === 1 ? '' : 's'}</span><span class="chip">${batches.length} batch${batches.length === 1 ? '' : 'es'}</span><span class="chip">${experiment.evaluationIds?.length || 0} evaluations</span></div></article>`; }).join('') : '<div class="empty-state"><strong>No experiments yet.</strong>Create a trial to preserve its formula history.</div>';
}

function renderEvaluationJournal() {
  const query = ($('#evaluation-search')?.value || '').toLowerCase(); const provenanceFilter = $('#evaluation-provenance')?.value || '';
  const evaluations = state.evaluations.slice().sort((a, b) => String(a.evaluatedAt).localeCompare(String(b.evaluatedAt)) || a.id.localeCompare(b.id)).filter(item => {
    const provenance = item.provenance || (item.isMeasured ? 'measured' : 'subjective'); const haystack = [item.intervalLabel, item.medium, item.environment, item.conditions, item.subjectiveNotes, item.measuredResults, item.predictedOutcome, ...(item.descriptors || [])].join(' ').toLowerCase(); return haystack.includes(query) && (!provenanceFilter || provenance === provenanceFilter || (provenanceFilter === 'ai-generated' && item.aiSuggestions?.length));
  });
  $('#evaluation-timeline').innerHTML = evaluations.length ? evaluations.map(evaluation => { const experiment = getExperiment(evaluation.experimentId); const batch = state.batches.find(item => item.id === evaluation.batchId); const revision = state.revisions.find(item => item.id === evaluation.revisionId); const provenance = evaluation.provenance || (evaluation.isMeasured ? 'measured' : 'subjective'); return `<article class="record evaluation-record"><div class="record-top"><div><h3>${esc(evaluation.intervalLabel || 'Unlabelled interval')}</h3><span class="record-date">${formatDate(evaluation.evaluatedAt)}${evaluation.elapsedMinutes !== undefined ? ` · ${esc(evaluation.elapsedMinutes)} min after mixing` : ''}</span></div><span class="status ${statusClass(provenance)}">${esc(provenance)}</span></div><p class="record-summary"><strong>${esc(experiment?.title || evaluation.experimentId)}</strong> · ${esc(batch?.batchCode || 'Batch not recorded')} · Revision ${esc(revision?.revision || '?')}</p><div class="chips">${(evaluation.descriptors || []).map(item => `<span class="chip">${esc(item)}</span>`).join('')}</div><p><strong>Subjective:</strong> ${esc(evaluation.subjectiveNotes || 'Not recorded')}</p>${evaluation.measuredResults ? `<p><strong>Measured:</strong> ${esc(evaluation.measuredResults)}</p>` : '<p class="muted"><strong>Measured:</strong> Not recorded</p>'}${evaluation.predictedOutcome ? `<p class="muted"><strong>Predicted:</strong> ${esc(evaluation.predictedOutcome)}</p>` : ''}<p class="muted">${esc(evaluation.medium || 'Medium unknown')} · ${esc(evaluation.environment || 'Environment unknown')} · ${esc(evaluation.conditions || 'Conditions not recorded')}</p>${evaluation.longevityObservation || evaluation.projectionObservation ? `<p class="muted">Longevity: ${esc(evaluation.longevityObservation || 'Not recorded')}${evaluation.longevityMethod ? ` (${esc(evaluation.longevityMethod)})` : ''} · Projection: ${esc(evaluation.projectionObservation || 'Not recorded')}${evaluation.projectionMethod ? ` (${esc(evaluation.projectionMethod)})` : ''}</p>` : ''}</article>`; }).join('') : '<div class="empty-state"><strong>No evaluations match this view.</strong>Record a sensory evaluation from a physical batch, or adjust the filters.</div>';
}

function coachOptions(items, current, label) { return `<option value="">${label}</option>${items.map(item => `<option value="${esc(item.id)}" ${item.id === current ? 'selected' : ''}>${esc(item.label)}</option>`).join('')}`; }
function renderCoachControls() {
  const experimentSelect = $('#coach-experiment'); const revisionSelect = $('#coach-revision'); const batchSelect = $('#coach-batch'); if (!experimentSelect) return;
  const currentExperiment = experimentSelect.value || state.experiments[0]?.id || '';
  experimentSelect.innerHTML = coachOptions(state.experiments.map(item => ({ id: item.id, label: `${item.experimentId} · ${item.title}` })), currentExperiment, 'Choose experiment');
  const experiment = state.experiments.find(item => item.id === experimentSelect.value) || state.experiments[0];
  if (!experiment) { revisionSelect.innerHTML = '<option value="">All revisions</option>'; batchSelect.innerHTML = '<option value="">All batches</option>'; return; }
  const revisions = state.revisions.filter(item => (experiment.formulaRevisionIds || []).includes(item.id)).map(item => ({ id: item.id, label: `Revision ${item.revision} · ${item.notes || 'No notes'}` }));
  const batches = state.batches.filter(item => (experiment.batchIds || []).includes(item.id)).map(item => ({ id: item.id, label: `${item.batchCode} · Revision ${state.revisions.find(revision => revision.id === item.formulaRevisionId)?.revision || '?'}` }));
  revisionSelect.innerHTML = coachOptions(revisions, revisionSelect.value, 'All revisions');
  batchSelect.innerHTML = coachOptions(batches, batchSelect.value, 'All physical batches');
}
function coachClaimHtml(item) { return `<article class="record coach-claim"><p>${esc(item.text)}</p><small class="muted">${esc(item.evidenceClass || 'recorded')} · Sources: ${item.sourceIds.map(sourceId => `<code>${esc(sourceId)}</code>`).join(', ')}</small></article>`; }
function renderCoachDebrief(debrief) {
  const claimSections = [['Experiment', debrief.claims.experiment], ['Formula revisions', debrief.claims.revisions], ['Physical batches', debrief.claims.batches], ['Sensory timeline', debrief.claims.sensoryTimeline], ['Recorded context', debrief.claims.recordedContext || []]].map(([heading, claims]) => `<section><p class="label">${heading.toUpperCase()}</p>${claims.length ? claims.map(coachClaimHtml).join('') : '<p class="muted">No linked records.</p>'}</section>`).join('');
  const revisionSection = debrief.claims.revisionComparisons.length ? `<section><p class="label">FORMULA REVISION DIFFERENCES</p>${debrief.claims.revisionComparisons.map(item => `<article class="record coach-claim"><p><strong>${esc(item.leftRevisionId)}</strong> → <strong>${esc(item.rightRevisionId)}</strong>: ${item.ingredientChanges.length ? esc(item.ingredientChanges.map(change => `${change.kind} ${change.key}`).join(', ')) : 'No ingredient changes recorded.'}</p>${item.warnings.length ? `<p class="muted">${item.warnings.map(warning => esc(warning)).join(' ')}</p>` : ''}<small class="muted">Sources: ${item.sourceIds.map(sourceId => `<code>${esc(sourceId)}</code>`).join(', ')}</small></article>`).join('')}</section>` : '';
  const missing = debrief.missingEvidence.length ? `<section class="coach-warning"><p class="label">MISSING OR CONTRADICTORY EVIDENCE</p><ul>${debrief.missingEvidence.map(item => `<li>${esc(item.warning || item.claim || 'Evidence issue')} · <code>${esc(item.sourceId || 'context')}</code></li>`).join('')}</ul></section>` : '<p class="inventory-ok">No missing or contradictory evidence was detected in the selected records.</p>';
  const proposal = debrief.proposedNextExperiment;
  $('#coach-output').innerHTML = `<div class="coach-result"><div class="coach-readonly"><strong>Read-only debrief.</strong> Nothing here changes formulas, stock, batches, or observations.</div><h2>${esc(debrief.title)}</h2>${claimSections}${revisionSection}${missing}<section><p class="label">PROPOSED NEXT CONTROLLED EXPERIMENT</p><div class="record"><p><strong>What to try:</strong> ${esc(proposal.primaryVariable.text)}</p><p><strong>Why:</strong> ${esc(proposal.why?.text || proposal.hypothesis.text)}</p><p><strong>What to hold constant:</strong> ${proposal.controls.map(item => esc(item)).join(' ')}</p><p><strong>What to record next:</strong> ${esc(proposal.whatToRecordNext?.text || 'Record the proposed response at the scheduled checkpoints.')}</p><p><strong>Observation schedule:</strong> ${proposal.observationSchedule.map(item => esc(item.label)).join(' · ')}</p><p><strong>Success criterion:</strong> ${esc(proposal.successCriterion.text)}</p><p><strong>Limitations:</strong> ${proposal.limitations.map(item => esc(item)).join(' ')}</p><p class="muted">${esc(proposal.note)}</p><small class="muted">Sources: ${proposal.hypothesis.sourceIds.map(sourceId => `<code>${esc(sourceId)}</code>`).join(', ')}</small></div></section><p class="muted">${esc(debrief.disclaimer)}</p></div>`;
}
function runCoach() { try { const context = buildExperimentCoachContext(state, { experimentId: $('#coach-experiment').value, revisionId: $('#coach-revision').value || undefined, batchId: $('#coach-batch').value || undefined }); renderCoachDebrief(createExperimentCoachDebrief(context)); } catch (error) { $('#coach-output').innerHTML = `<div class="empty-state"><strong>Coach could not build this debrief.</strong><p>${esc(error.message)}</p></div>`; } }

function renderMaterials() {
  const summary = inventorySummary(state);
  $('#inventory-summary').innerHTML = [['LOTS', summary.lots.length], ['KNOWN ON-HAND', summary.lots.filter(item => item.balanceKnown).length], ['RECONCILIATION NEEDED', summary.unknownLots.length], ['LOW STOCK / DATE WARNINGS', summary.lowStock.length + summary.dateWarnings.length]].map(([label, value]) => `<div><span>${label}</span><strong>${value}</strong></div>`).join('');
  const warnings = [...summary.unknownLots.map(item => `<div class="inventory-warning"><strong>${esc(item.materialName)} · ${esc(item.lot.lotCode || item.lot.id)}</strong><span>Opening quantity unknown. ${item.balance == null ? 'No compatible quantity is recorded yet.' : `Recorded balance ${item.balance.toFixed(4)} ${esc(item.unit)} is a consumption floor, not measured on-hand stock.`}</span></div>`), ...summary.lowStock.map(item => `<div class="inventory-warning"><strong>Low stock · ${esc(item.materialName)} · ${esc(item.lot.lotCode || item.lot.id)}</strong><span>${item.balance.toFixed(4)} ${esc(item.unit)} at or below threshold ${esc(item.lot.lowStockThreshold)} ${esc(item.unit)}.</span></div>`), ...summary.dateWarnings.map(item => `<div class="inventory-warning"><strong>Date reminder · ${esc(item.materialName)} · ${esc(item.lot.lotCode || item.lot.id)}</strong><span>${esc(item.warnings.filter(warning => warning.includes('date')).join(' '))} Operational reminder only; not a safety determination.</span></div>`)].join('');
  $('#inventory-warnings').innerHTML = warnings || '<div class="inventory-ok">No inventory warnings for recorded dates, thresholds, or opening balances.</div>';
  $('#material-list').innerHTML = state.materials.length ? `<table><thead><tr><th>MATERIAL</th><th>LOT / ON-HAND</th><th>IDENTITY &amp; STORAGE</th><th>HISTORY</th><th>ACTIONS</th></tr></thead><tbody>${state.materials.map(material => { const lots = material.lots || []; const used = state.batches.flatMap(batch => batch.actualAdditions || []).filter(addition => addition.materialId === material.id).length; return `<tr><td><strong>${esc(material.name)}</strong><br><span class="muted">${esc(material.supplier || 'Supplier not recorded')} · ${used} batch use${used === 1 ? '' : 's'}</span></td><td>${lots.length ? lots.map(lot => { const status = stockStatus(state, lot.id); const unit = status.unit || '?'; const history = lotMovementHistory(state, lot.id); const label = lot.lotCode || lot.id; const balance = status.balanceKnown ? `${status.balance.toFixed(4)} ${esc(unit)}` : `Unknown${status.balance == null ? '' : ` · floor ${status.balance.toFixed(4)} ${esc(unit)}`}`; return `<div class="lot-ledger"><div class="lot-meta"><strong>${esc(label)}</strong><small>${esc(lot.receivedAt || 'Received date not recorded')} · ${lot.purity == null ? 'Purity unknown' : `${lot.purity}% purity`} · ${lot.expiryDate ? `Expiry ${esc(lot.expiryDate)}` : 'Expiry unknown'}</small><span class="${status.balanceKnown ? '' : 'unknown-stock'}">On-hand: ${balance}</span></div><div class="inventory-actions"><button class="icon-button" data-action="new-movement" data-material-id="${esc(material.id)}" data-lot-id="${esc(lot.id)}" type="button">Movement</button><button class="icon-button" data-action="reconcile-lot" data-lot-id="${esc(lot.id)}" type="button">Reconcile</button></div><details><summary>${history.length} movement${history.length === 1 ? '' : 's'} · ${history.filter(item => item.batchId).length} linked batch${history.filter(item => item.batchId).length === 1 ? '' : 'es'}</summary><ol class="ledger-history">${history.map(movement => { const sign = ['opening', 'receipt', 'return'].includes(movement.movementType) || (['adjustment', 'correction'].includes(movement.movementType) && movement.direction === 'increase') ? '+' : '-'; const batch = movement.batchId ? state.batches.find(item => item.id === movement.batchId) : null; return `<li><span class="${sign === '+' ? 'movement-positive' : 'movement-negative'}">${sign}${esc(movement.quantity)} ${esc(movement.unit)}</span> · ${esc(movement.movementType)} · ${formatDate(movement.occurredAt)}${batch ? ` · ${esc(batch.batchCode)}` : ''}${movement.note ? ` · ${esc(movement.note)}` : ''}</li>`; }).join('')}</ol></details></div>`; }).join('') : '<span class="muted">No lots recorded.</span>'}</td><td><div>${esc(material.canonicalIdentity || 'Identity not recorded')}</div><small class="muted">${esc(material.productReference || 'Product reference not recorded')}<br>${esc(material.storageNotes || 'Storage notes not recorded')}<br>${esc(material.safetyReference || 'Safety reference not recorded')}</small></td><td>${lots.reduce((sum, lot) => sum + lotMovementHistory(state, lot.id).length, 0)} movements</td><td><div class="inventory-actions"><button class="icon-button" data-action="new-lot" data-material-id="${esc(material.id)}" type="button">Add lot</button><button class="icon-button" data-action="new-movement" data-material-id="${esc(material.id)}" type="button">Record movement</button></div></td></tr>`; }).join('')}</tbody></table>` : '<div class="empty-state"><strong>No materials recorded.</strong>Add only what you know; unknown supplier, quantity, and chemical properties stay visible as unknown.</div>';
  $('#recent-movements').innerHTML = summary.recentMovements.length ? summary.recentMovements.map(movement => `<article class="record"><div class="record-top"><strong>${esc(movement.movementType)}</strong><span class="record-date">${formatDate(movement.occurredAt)} · ${esc(movement.quantity)} ${esc(movement.unit)}</span></div><p class="record-summary">${esc(movement.note || 'No reason recorded.')}${movement.batchId ? ` · Batch ${esc(state.batches.find(batch => batch.id === movement.batchId)?.batchCode || movement.batchId)}` : ''}</p></article>`).join('') : '<div class="empty-state">No ledger movements yet.</div>';
}

function renderEquipment() {
  const query = ($('#equipment-search')?.value || '').toLowerCase(); const statusFilter = $('#equipment-status-filter')?.value || ''; const verificationFilter = $('#equipment-verification-filter')?.value || '';
  const records = equipmentSummary(state).filter(record => { const item = record.equipment; const haystack = [item.name, item.equipmentType, item.manufacturer, item.model, item.serialNumber, item.location].join(' ').toLowerCase(); return haystack.includes(query) && (!statusFilter || item.status === statusFilter) && (!verificationFilter || record.verification.status === verificationFilter); });
  const all = equipmentSummary(state); const counts = { total: all.length, verified: all.filter(item => ['verified', 'conditional'].includes(item.verification.status)).length, warnings: all.filter(item => item.warnings.length).length, measurements: state.measurements.length };
  $('#equipment-summary').innerHTML = [['EQUIPMENT', counts.total], ['VERIFIED / CONDITIONAL', counts.verified], ['ACTIVE WARNINGS', counts.warnings], ['MEASUREMENTS', counts.measurements]].map(([label, value]) => `<div><span>${label}</span><strong>${value}</strong></div>`).join('');
  $('#equipment-warnings').innerHTML = all.flatMap(record => record.warnings.map(warning => `<div class="inventory-warning"><strong>${esc(record.equipment.name)}</strong><span>${esc(warning)}</span></div>`)).join('') || '<div class="inventory-ok">No equipment warnings. Unknown verification remains visible when no evidence is recorded.</div>';
  $('#equipment-list').innerHTML = records.length ? records.map(record => { const item = record.equipment; const verification = record.verification; const history = [...record.maintenance.map(event => ({ ...event, kind: event.eventType, date: event.occurredAt })), ...record.verification.events.map(event => ({ ...event, kind: `verification: ${event.outcome}`, date: event.performedAt }))].sort((a, b) => String(b.date).localeCompare(String(a.date))); return `<article class="record equipment-card" data-equipment-id="${esc(item.id)}"><div class="record-top"><div><p class="label">${esc(item.equipmentType)} · ${esc(item.location || 'Location not recorded')}</p><h2>${esc(item.name)}</h2><span class="record-date">${esc(item.manufacturer || 'Manufacturer unknown')}${item.model ? ` · ${esc(item.model)}` : ''}${item.serialNumber ? ` · S/N ${esc(item.serialNumber)}` : ''}</span></div><span class="status ${statusClass(item.status)}">${esc(item.status)}</span></div><div class="chips"><span class="chip">Verification: ${esc(verification.status)}</span>${item.resolution ? `<span class="chip">Resolution ${esc(item.resolution)} ${esc(item.resolutionUnit || '')}</span>` : '<span class="chip unknown-stock">Resolution unknown</span>'}<span class="chip">${record.measurements.length} measurement${record.measurements.length === 1 ? '' : 's'}</span></div>${record.warnings.length ? `<p class="unknown-stock">${record.warnings.map(warning => esc(warning)).join(' ')}</p>` : '<p class="inventory-ok">No current warnings.</p>'}<div class="form-actions"><button class="icon-button" data-action="edit-equipment" data-id="${esc(item.id)}">Edit</button><button class="icon-button" data-action="new-verification" data-id="${esc(item.id)}">Verification</button><button class="icon-button" data-action="new-maintenance" data-id="${esc(item.id)}">Maintenance</button><button class="icon-button" data-action="new-measurement" data-id="${esc(item.id)}">Measurement</button></div><details><summary>${history.length} history event${history.length === 1 ? '' : 's'} · ${record.measurements.length} linked measurement${record.measurements.length === 1 ? '' : 's'}</summary><div class="ledger-history">${history.map(event => `<p><strong>${esc(event.kind)}</strong> · ${formatDate(event.date)}${event.notes ? ` · ${esc(event.notes)}` : ''}</p>`).join('') || '<p class="muted">No history recorded.</p>'}${record.measurements.map(measurement => `<p><strong>measurement</strong> · ${formatDate(measurement.measuredAt)} · ${esc(measurement.quantityType)} ${esc(measurement.value)} ${esc(measurement.unit)}${measurement.method ? ` · ${esc(measurement.method)}` : ''}</p>`).join('')}</div></details></article>`; }).join('') : '<div class="empty-state"><strong>No equipment matches this view.</strong><p>Register the equipment before recording verification or measurements.</p></div>';
}

function renderPurchases() {
  const purchases = state.purchases.slice().sort((a, b) => String(b.purchaseDate).localeCompare(String(a.purchaseDate)) || b.id.localeCompare(a.id));
  const summaries = purchases.map(purchase => purchaseSummary(state, purchase.id)); const unverified = summaries.filter(summary => !summary.receiptVerified).length; const uncosted = state.batches.reduce((sum, batch) => sum + calculateBatchCost(state, batch.id).uncosted.length, 0);
  $('#purchase-summary').innerHTML = [['PURCHASES', purchases.length], ['RECEIPT-VERIFIED', summaries.filter(summary => summary.receiptVerified).length], ['UNVERIFIED PRICES', unverified], ['UNCOSTED ADDITIONS', uncosted]].map(([label, value]) => `<div><span>${label}</span><strong>${value}</strong></div>`).join('');
  $('#purchase-warnings').innerHTML = summaries.filter(summary => !summary.receiptVerified).map(summary => `<div class="inventory-warning"><strong>${esc(summary.purchase.supplier)} · ${esc(summary.purchase.receiptNumber || summary.purchase.id)}</strong><span>Price recorded without receipt evidence; it is not receipt-verified and will not contribute to a complete batch cost.</span></div>`).join('') || '<div class="inventory-ok">All recorded purchase prices have receipt evidence.</div>';
  $('#purchase-list').innerHTML = purchases.length ? purchases.map(purchase => { const summary = purchaseSummary(state, purchase.id); const lineNames = summary.lineItems.map(line => { const material = state.materials.find(item => item.id === line.materialId); const lot = material?.lots?.find(item => item.id === line.materialLotId); return `<li><strong>${esc(material?.name || line.materialId)}</strong> · ${esc(line.quantity)} ${esc(line.unit)} · ${esc(line.unitPrice)} ${esc(purchase.currency)}/${esc(line.unit)} · line ${esc(line.lineTotal)} ${esc(purchase.currency)} · lot ${esc(lot?.lotCode || line.materialLotId)}</li>`; }).join(''); return `<article class="record"><div class="record-top"><div><p class="label">${esc(purchase.purchaseDate)} · ${esc(purchase.currency)}</p><h2>${esc(purchase.supplier)}</h2><span class="record-date">${esc(purchase.receiptNumber || 'Receipt reference not recorded')} · ${summary.receiptVerified ? 'Receipt evidence attached' : 'Receipt evidence missing'}</span></div><span class="status ${summary.receiptVerified ? 'verified' : 'unknown-stock'}">${summary.receiptVerified ? 'receipt-verified' : 'unverified'}</span></div><div class="chips"><span class="chip">Subtotal ${esc(summary.subtotal.toFixed(2))} ${esc(purchase.currency)}</span><span class="chip">Total ${esc(summary.total.toFixed(2))} ${esc(purchase.currency)}</span><span class="chip">${summary.lineItems.length} line${summary.lineItems.length === 1 ? '' : 's'}</span></div><ul>${lineNames}</ul><p class="muted">${esc(purchase.notes || 'No purchase notes recorded.')}</p><div class="form-actions"><button class="icon-button" data-action="edit-purchase" data-id="${esc(purchase.id)}">Edit purchase</button></div></article>`; }).join('') : '<div class="empty-state"><strong>No purchases recorded.</strong><p>Add receipt-backed purchase lines before expecting a complete batch cost.</p></div>';
}

function blindSampleDetails(sample) { const batch = state.batches.find(item => item.id === sample.batchId); const experiment = state.experiments.find(item => item.id === sample.experimentId); const revision = state.revisions.find(item => item.id === sample.revisionId); return { batch, experiment, revision }; }
function renderBlindSessions() {
  const sessions = state.blindSessions.slice().sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)) || b.id.localeCompare(a.id));
  $('#blind-session-list').innerHTML = sessions.length ? sessions.map(session => { const samples = session.sampleIds.map(id => state.blindSamples.find(item => item.id === id)).filter(Boolean).sort((a, b) => (a.position || 999) - (b.position || 999)); const evaluations = state.evaluations.filter(item => item.blindSessionId === session.id); const draftDetails = session.status === 'draft' ? `<ul>${samples.map(sample => { const details = blindSampleDetails(sample); return `<li>${esc(details.batch?.batchCode || sample.batchId)} · ${esc(details.experiment?.title || sample.experimentId)} · Revision ${esc(details.revision?.revision || sample.revisionId)}</li>`; }).join('')}</ul>` : ''; const blindCodes = session.status !== 'draft' ? `<div class="chips">${samples.map(sample => `<span class="chip">${esc(sample.blindCode)} · ${evaluations.filter(item => item.blindSampleId === sample.id).length} observation${evaluations.filter(item => item.blindSampleId === sample.id).length === 1 ? '' : 's'}</span>`).join('')}</div>` : ''; const actions = session.status === 'draft' ? `<button class="primary-button" data-action="randomize-blind" data-id="${esc(session.id)}">Randomize samples</button>` : session.status === 'randomized' ? `<button class="primary-button" data-action="start-blind" data-id="${esc(session.id)}">Begin evaluator view</button>` : session.status === 'in-progress' ? `${samples.map(sample => `<button class="icon-button" data-action="blind-observe" data-session-id="${esc(session.id)}" data-sample-id="${esc(sample.id)}">Observe ${esc(sample.blindCode)}</button>`).join('')}<button class="secondary-button" data-action="lock-blind" data-id="${esc(session.id)}">Lock observations</button>` : session.status === 'locked' ? '<span class="muted">Observations locked; identities remain hidden.</span><button class="primary-button" data-action="unblind-session" data-id="' + esc(session.id) + '">Unblind session</button>' : '<span class="inventory-ok">Session unblinded; mapping is available below.</span>'; const mapping = session.status === 'unblinded' ? `<h3>CODE-TO-SAMPLE MAPPING</h3><div class="table-wrap"><table><thead><tr><th>BLIND CODE</th><th>BATCH</th><th>EXPERIMENT / REVISION</th><th>OBSERVATIONS</th></tr></thead><tbody>${samples.map(sample => { const details = blindSampleDetails(sample); const count = evaluations.filter(item => item.blindSampleId === sample.id).length; return `<tr><td>${esc(sample.blindCode)}</td><td>${esc(details.batch?.batchCode || sample.batchId)}</td><td>${esc(details.experiment?.title || sample.experimentId)} · Revision ${esc(details.revision?.revision || sample.revisionId)}</td><td>${count}</td></tr>`; }).join('')}</tbody></table></div>` : ''; return `<article class="record blind-session-card" data-blind-session-id="${esc(session.id)}"><div class="record-top"><div><p class="label">${esc(session.sessionDate)} · ${esc(session.evaluatorLabel || 'Evaluator not recorded')}</p><h2>${esc(session.name)}</h2><span class="record-date">${esc(session.purpose)} · ${samples.length} candidate samples</span></div><span class="status ${statusClass(session.status)}">${esc(session.status)}</span></div>${session.status === 'draft' ? `<p class="muted">Draft candidate identities are visible to the session creator before randomization.</p>${draftDetails}` : `<p class="muted">Evaluator-facing records use opaque codes only until explicit unblinding.</p>${blindCodes}`}${session.protocol ? `<p><strong>Protocol:</strong> ${esc(session.protocol)}</p>` : ''}${session.conditions ? `<p class="muted"><strong>Conditions:</strong> ${esc(session.conditions)}</p>` : ''}<div class="form-actions">${actions}</div>${mapping}</article>`; }).join('') : '<div class="empty-state"><strong>No blind sessions yet.</strong><p>Create a session from two or more existing physical batches.</p></div>';
}

function maturationCheckpointStatusClass(status) { return status === 'completed' ? 'verified' : status === 'overdue' ? 'unknown-stock' : status; }
function renderMaturationPlans() {
  const target = $('#maturation-plan-list'); if (!target) return;
  const plans = state.maturationPlans.slice().sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)) || b.id.localeCompare(a.id));
  target.innerHTML = plans.length ? plans.map(plan => { const timeline = maturationPlanTimeline(state, plan.id); const batch = timeline.batch; const observations = timeline.observations; const checkpointRows = timeline.checkpoints.map(row => `<li><span class="status ${maturationCheckpointStatusClass(row.status)}">${esc(row.status)}</span> <strong>${esc(row.checkpoint.label)}</strong> · planned ${formatDate(row.plannedAt)}${row.latestObservation ? ` · observed ${formatDate(row.latestObservation.observedAt)}` : ''}</li>`).join(''); const observationRows = observations.map(item => `<article class="record"><div class="record-top"><div><strong>${esc(timeline.checkpoints.find(row => row.checkpoint.id === item.checkpointId)?.checkpoint.label || item.checkpointId)}</strong><span class="record-date">${formatDate(item.observedAt)} · ${esc(item.elapsedMinutes)} min from start</span></div><span class="status ${statusClass(item.evidenceStatus)}">${esc(item.evidenceStatus || 'complete')}</span></div><p><strong>Appearance:</strong> ${esc(item.appearance || 'Not recorded')} · <strong>Clarity:</strong> ${esc(item.clarity || 'Not recorded')}</p><p><strong>Subjective odour:</strong> ${esc(item.subjectiveOdour || 'Not recorded')}</p><p class="muted">${esc(item.storageLocation || 'Location unknown')} · ${esc(item.containerType || 'Container unknown')} · ${esc(item.lightExposure || 'Light exposure unknown')}${item.deviations ? ` · Deviation: ${esc(item.deviations)}` : ''}</p>${item.measuredValues?.length ? `<p><strong>Measured:</strong> ${item.measuredValues.map(value => `${esc(value.label)} ${esc(value.value)} ${esc(value.unit)}`).join(' · ')}</p>` : '<p class="muted">Measured value not recorded.</p>'}</article>`).join(''); return `<article class="record maturation-plan" data-maturation-plan-id="${esc(plan.id)}"><div class="record-top"><div><p class="label">${esc(timeline.experiment?.experimentId || plan.experimentId)} · ${esc(batch?.batchCode || plan.batchId)}</p><h2>${esc(plan.name)}</h2><span class="record-date">Start ${formatDate(plan.maturationStartAt)} · Revision ${esc(timeline.revision?.revision || plan.revisionId)}</span></div><span class="status ${statusClass(timeline.evidenceStatus)}">${esc(timeline.evidenceStatus)}</span></div><p class="record-summary">${esc(plan.purpose)}</p><div class="chips"><span class="chip">${timeline.elapsedMinutes} min since start</span><span class="chip">${observations.length} observation${observations.length === 1 ? '' : 's'}</span><span class="chip">${timeline.checkpoints.filter(item => item.status === 'completed').length}/${timeline.checkpoints.length} checkpoints completed</span></div><p class="muted">Storage: ${esc(plan.storageConditions || 'Not recorded')}</p><h3>PLANNED SCHEDULE</h3><ul>${checkpointRows}</ul><div class="form-actions">${timeline.checkpoints.filter(item => item.status !== 'completed').map(row => `<button class="icon-button" data-action="new-maturation-observation" data-plan-id="${esc(plan.id)}" data-checkpoint-id="${esc(row.checkpoint.id)}">Observe ${esc(row.checkpoint.label)}</button>`).join('')}<button class="secondary-button" data-action="open-maturation-plan" data-id="${esc(plan.id)}">Open timeline</button></div>${observationRows ? `<h3>OBSERVATION TIMELINE</h3>${observationRows}` : '<div class="empty-state">No observations recorded yet. Unobserved and overdue checkpoints remain evidence gaps.</div>'}</article>`; }).join('') : '<div class="empty-state"><strong>No maturation plans yet.</strong><p>Create one from an existing physical batch to schedule custom checkpoints.</p></div>';
}

function renderExperimentDesigns() {
  const target = $('#experiment-design-list'); if (!target) return;
  const designs = state.experimentDesigns.slice().sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)) || b.id.localeCompare(a.id));
  target.innerHTML = designs.length ? designs.map(design => { const review = experimentDesignReview(state, design.id); const baseExperiment = getExperiment(design.experimentId); const runRows = review.runs.map(run => { const condition = review.conditions.find(item => item.condition.id === run.conditionId)?.condition; const batch = state.batches.find(item => item.id === run.batchId); return `<tr data-design-run-id="${esc(run.id)}"><td>${esc(run.randomizedOrder || run.plannedOrder)}</td><td>${esc(condition?.name || run.conditionId)}<br><small>Replicate ${esc(run.replicateNumber)}</small></td><td>${esc(run.status)}</td><td>${esc(batch?.batchCode || 'Not linked')}</td><td><button class="icon-button" data-action="edit-design-run" data-id="${esc(run.id)}">Update run</button></td></tr>`; }).join(''); const conditionSummary = review.conditions.map(item => `<li><strong>${esc(item.condition.name)}</strong>: ${item.completedReplicates}/${item.plannedReplicates} completed${item.responses.filter(response => response.summary).length ? ` · ${item.responses.filter(response => response.summary).map(response => `${esc(response.response.name)} mean ${response.summary.mean.toFixed(3)} ${esc(response.summary.unit)}`).join(' · ')}` : ''}</li>`).join(''); return `<article class="record experiment-design-card" data-experiment-design-id="${esc(design.id)}"><div class="record-top"><div><p class="label">${esc(baseExperiment?.experimentId || design.experimentId)} · ${design.randomizedAt ? 'EXECUTION ORDER RANDOMIZED' : 'PLANNED ORDER'}</p><h2>${esc(design.name)}</h2><span class="record-date">${esc(design.researchQuestion)}</span></div><span class="status ${review.canCompare ? 'verified' : 'unknown-stock'}">${review.canCompare ? 'repeatability review available' : 'incomplete replication'}</span></div><p><strong>Hypothesis:</strong> ${esc(design.hypothesis)}</p><div class="chips"><span class="chip">${review.runs.filter(run => ['completed', 'deviated'].includes(run.status)).length}/${review.runs.length} runs completed</span><span class="chip">${design.factorIds.length} factors</span><span class="chip">${design.responseIds.length} responses</span><span class="chip">${review.warnings.length} warnings</span></div><ul>${conditionSummary}</ul><div class="form-actions"><button class="primary-button" data-action="randomize-design" data-id="${esc(design.id)}">${design.randomizedAt ? 'Execution order saved' : 'Randomize execution order'}</button></div><div class="table-wrap"><table><thead><tr><th>ORDER</th><th>CONDITION / REPLICATE</th><th>STATUS</th><th>BATCH</th><th>ACTION</th></tr></thead><tbody>${runRows}</tbody></table></div>${review.warnings.length ? `<div class="coach-warning"><strong>Evidence limits</strong><ul>${review.warnings.map(warning => `<li>${esc(warning)}</li>`).join('')}</ul></div>` : '<div class="inventory-ok">All planned conditions have at least two completed replicates.</div>'}<div class="compare-note"><strong>Comparison note:</strong> descriptive summaries use only recorded, compatible response values. Differences are not causal claims or statistical significance.</div></article>`; }).join('') : '<div class="empty-state"><strong>No experiment designs yet.</strong><p>Define factors, conditions, response measures, and independent replicates before running a controlled comparison.</p></div>';
}

function renderCompare() {
  const records = state.revisions.map(revision => { const experiment = getExperiment(revision.experimentId); return { value: revision.id, label: `${experiment?.experimentId || 'Experiment'} · Revision ${revision.revision} · ${experiment?.title || ''}`, revision, experiment }; });
  const options = records.map(record => `<option value="${esc(record.value)}">${esc(record.label)}</option>`).join(''); const a = $('#compare-a'); const b = $('#compare-b');
  const previousA = a.value; const previousB = b.value; a.innerHTML = options; b.innerHTML = options; a.value = records.some(record => record.value === previousA) ? previousA : records[0]?.value || ''; b.value = records.some(record => record.value === previousB) ? previousB : records[1]?.value || records[0]?.value || '';
  if (records.length < 2) { $('#comparison').innerHTML = '<div class="empty-state"><strong>Two revisions make a comparison.</strong>Create another formula revision to see changes side by side.</div>'; return; }
  const first = state.revisions.find(item => item.id === a.value) || state.revisions[0]; const second = state.revisions.find(item => item.id === b.value) || state.revisions[1];
  const comparison = compareRevisions(state, first.id, second.id);
  const changes = comparison.ingredientChanges.length ? comparison.ingredientChanges.map(change => `<li>${esc(change.kind)} · ${esc(change.after?.materialName || change.before?.materialName || change.key)}</li>`).join('') : '<li>No ingredient changes recorded.</li>';
  $('#comparison').innerHTML = [first, second].map(revision => { const experiment = getExperiment(revision.experimentId); const evaluations = revision.id === first.id ? comparison.leftEvaluations : comparison.rightEvaluations; const batches = revision.id === first.id ? comparison.leftBatchTotals : comparison.rightBatchTotals; return `<article class="comparison-card"><p class="label">REVISION ${revision.revision} · ${esc(experiment?.experimentId || '')}</p><h2>${esc(experiment?.title || 'Untitled experiment')}</h2><p>${esc(revision.notes || 'No revision notes recorded.')}</p><h3>INGREDIENTS</h3>${revision.ingredients?.length ? `<div class="chips">${revision.ingredients.map(item => `<span class="chip">${esc(item.materialName || item.materialId)} · ${esc(item.quantity)} ${esc(item.unit)}${item.lotId ? ` · lot ${esc(item.lotId)}` : ''}</span>`).join('')}</div>` : '<p>No ingredients recorded.</p>'}<h3>ACTUAL BATCHES</h3><p>${batches.length ? batches.map(batch => `${esc(batch.batchId)}: planned ${esc(batch.plannedAmount)} ${esc(batch.plannedUnit)}, actual ${batch.actual ? esc(batch.actual.totalAmount) : 'not recorded'} ${esc(batch.actual?.unit || batch.plannedUnit)}`).join('<br>') : 'No actual batch recorded.'}</p><h3>RECORDED EVIDENCE</h3><p>${evaluations.length} linked evaluation${evaluations.length === 1 ? '' : 's'} · ${evaluations.filter(item => item.isMeasured).length} marked measured · ${evaluations.filter(item => !item.isMeasured).length} subjective</p></article>`; }).join('') + `<div class="compare-note"><strong>Recorded ingredient changes</strong><ul>${changes}</ul>${comparison.warnings.length ? `<p>${comparison.warnings.map(warning => esc(warning)).join(' ')}</p>` : ''}<span>A changed score or descriptor is a recorded difference, not proof that one formula caused it. Compare conditions and evaluation intervals before drawing conclusions.</span></div>`;
}

function pipeRows(value) {
  return String(value || '').split('\n').map(line => line.trim()).filter(Boolean).map(line => line.split('|').map(part => part.trim()));
}

function boolField(value, fallback = true) { return value === undefined || value === '' ? fallback : ['true', 'yes', '1', 'required'].includes(String(value).toLowerCase()); }

function methodDraftInput(form) {
  const values = Object.fromEntries(new FormData(form));
  const steps = pipeRows(values.steps).map((parts, index) => ({ id: parts[0] || undefined, order: index + 1, type: parts[1] || 'instruction', title: parts[2], instruction: parts[3] || '', required: boolField(parts[4]), measurementName: parts[5] || undefined, unit: parts[6] || undefined, condition: parts[7] || undefined, expected: parts[8] || undefined }));
  const materials = pipeRows(values.materials).map(parts => ({ name: parts[0], quantity: parts[1] === '' || parts[1] === undefined ? undefined : Number(parts[1]), unit: parts[2] || undefined, notes: parts[3] || '' }));
  const equipment = pipeRows(values.equipment).map(parts => ({ name: parts[0], purpose: parts[1] || '', notes: parts[2] || '' }));
  const measurements = pipeRows(values.measurements).map(parts => { const kind = parts[2] || ''; const criterion = kind ? { kind, unit: parts[1], value: ['equals', 'at-least', 'at-most'].includes(kind) ? Number(parts[3]) : undefined, min: kind === 'range' && parts[3] !== '' ? Number(parts[3]) : undefined, max: kind === 'range' && parts[4] !== '' ? Number(parts[4]) : undefined } : undefined; return { name: parts[0], unit: parts[1], criterion, notes: parts[5] || '' }; });
  const conditions = pipeRows(values.conditions).map(parts => ({ name: parts[0], expected: parts[1], unit: parts[2] || undefined, required: boolField(parts[3]) }));
  const observations = pipeRows(values.observations).map(parts => ({ name: parts[0], prompt: parts[1], required: boolField(parts[2]) }));
  const evidenceRequirements = pipeRows(values.evidence).map(parts => ({ name: parts[0], required: boolField(parts[1]) }));
  return { title: values.title, purpose: values.purpose, scope: values.scope, author: values.author, tags: tags(values.tags), steps, materials, equipment, measurements, conditions, observations, evidenceRequirements };
}

function methodEditorValues(version) {
  const rows = version?.steps || [{ type: 'instruction', title: '', instruction: '', required: true }];
  return {
    title: version?.title || '', purpose: version?.purpose || '', scope: version?.scope || '', author: version?.author || 'Local user', tags: version?.tags?.join(', ') || '',
    steps: rows.map(item => [item.id || '', item.type, item.title, item.instruction || '', item.required === false ? 'optional' : 'required', item.measurementName || '', item.unit || '', item.condition || '', item.expected || ''].join(' | ')).join('\n'),
    materials: (version?.materials || []).map(item => [item.name, item.quantity ?? '', item.unit || '', item.notes || ''].join(' | ')).join('\n'),
    equipment: (version?.equipment || []).map(item => [item.name, item.purpose || '', item.notes || ''].join(' | ')).join('\n'),
    measurements: (version?.measurements || []).map(item => [item.name, item.unit, item.criterion?.kind || '', item.criterion?.kind === 'range' ? item.criterion?.min ?? '' : item.criterion?.value ?? '', item.criterion?.kind === 'range' ? item.criterion?.max ?? '' : '', item.notes || ''].join(' | ')).join('\n'),
    conditions: (version?.conditions || []).map(item => [item.name, item.expected, item.unit || '', item.required === false ? 'optional' : 'required'].join(' | ')).join('\n'),
    observations: (version?.observations || []).map(item => [item.name, item.prompt, item.required === false ? 'optional' : 'required'].join(' | ')).join('\n'),
    evidence: (version?.evidenceRequirements || []).map(item => [item.name, item.required === false ? 'optional' : 'required'].join(' | ')).join('\n')
  };
}

function renderMethods() {
  const target = $('#method-list'); if (!target) return;
  const query = ($('#method-search')?.value || '').toLowerCase(); const status = $('#method-status-filter')?.value || '';
  const methods = state.methods.filter(method => (!status || method.status === status) && `${method.title} ${method.purpose} ${method.scope} ${(method.tags || []).join(' ')}`.toLowerCase().includes(query)).sort((a, b) => String(b.updatedAt).localeCompare(String(a.updatedAt)));
  target.innerHTML = methods.length ? methods.map(method => { const published = state.methodVersions.filter(item => item.methodId === method.id && item.status === 'published').sort((a, b) => b.version - a.version); const executions = state.methodExecutions.filter(item => item.methodId === method.id); const latest = published[0]; return `<article class="record method-card" data-method-id="${esc(method.id)}"><div class="record-top"><div><p class="label">${esc(method.author)} · ${esc(method.status)}</p><h2>${esc(method.title)}</h2><span class="record-date">${esc(method.scope || 'Scope not recorded')}</span></div><span class="status ${latest ? 'verified' : 'unknown-stock'}">${latest ? `v${latest.version} published` : 'Draft only'}</span></div><p>${esc(method.purpose)}</p><div class="chips"><span class="chip">${published.length} published version${published.length === 1 ? '' : 's'}</span><span class="chip">${executions.length} execution${executions.length === 1 ? '' : 's'}</span>${(method.tags || []).slice(0, 4).map(tag => `<span class="chip">${esc(tag)}</span>`).join('')}</div><div class="form-actions"><button class="primary-button" data-action="open-method" data-id="${esc(method.id)}">Open method</button>${latest ? `<button class="icon-button" data-action="new-method-execution" data-id="${esc(method.id)}">Execute v${latest.version}</button>` : ''}</div></article>`; }).join('') : '<div class="empty-state"><strong>No methods match this view.</strong><p>Create a draft method to make a repeatable procedure reusable.</p></div>';
}

function showMethodForm(methodId = '') {
  const method = methodId ? state.methods.find(item => item.id === methodId) : null; const version = method ? state.methodVersions.find(item => item.id === method.draftVersionId) : null; const values = methodEditorValues(version); values.author = method?.author || values.author;
  $('#record-dialog-content').innerHTML = `<form id="method-form" class="dialog-content" data-method-id="${esc(methodId)}"><p class="label">METHOD / SOP LIBRARY</p><h2>${method ? 'Edit draft method' : 'New draft method'}</h2><p class="muted">Use one pipe-separated row per item. Published versions are immutable; this editor changes only the draft.</p><div class="form-grid"><label>Title<input name="title" required value="${esc(values.title)}"></label><label>Author / owner<input name="author" value="${esc(values.author)}"></label><label>Scope<input name="scope" value="${esc(values.scope)}" placeholder="e.g. gravimetric dilution check"></label><label>Tags<input name="tags" value="${esc(values.tags)}" placeholder="measurement, repeatability"></label></div><label>Purpose<textarea name="purpose" rows="3" required>${esc(values.purpose)}</textarea></label><label>Procedure steps<textarea name="steps" rows="7" required aria-describedby="method-steps-help">${esc(values.steps)}</textarea><small id="method-steps-help" class="muted">id | type | title | instruction | required/optional | measurement name | unit | condition | expected. Types: instruction, measurement, observation, wait, condition-checkpoint, review.</small></label><div class="form-grid"><label>Required materials<textarea name="materials" rows="5" placeholder="name | quantity | unit | notes">${esc(values.materials)}</textarea></label><label>Required equipment<textarea name="equipment" rows="5" placeholder="name | purpose | notes">${esc(values.equipment)}</textarea></label><label>Measurements<textarea name="measurements" rows="5" placeholder="name | unit | criterion kind | value/min | max | notes">${esc(values.measurements)}</textarea></label><label>Required conditions<textarea name="conditions" rows="5" placeholder="name | expected | unit | required/optional">${esc(values.conditions)}</textarea></label><label>Required observations<textarea name="observations" rows="5" placeholder="name | prompt | required/optional">${esc(values.observations)}</textarea></label><label>Evidence requirements<textarea name="evidence" rows="5" placeholder="name | required/optional">${esc(values.evidence)}</textarea></label></div><div class="form-actions"><button type="button" class="text-button" data-close="record-dialog">Cancel</button><button class="primary-button" type="submit">Save draft</button></div></form>`;
  openDialog('record-dialog');
}

function showMethodDetail(methodId) {
  const method = state.methods.find(item => item.id === methodId); if (!method) return; const versions = state.methodVersions.filter(item => item.methodId === methodId).sort((a, b) => (b.version - a.version) || String(b.createdAt).localeCompare(String(a.createdAt))); const executions = state.methodExecutions.filter(item => item.methodId === methodId).sort((a, b) => String(b.startedAt).localeCompare(String(a.startedAt))); const draft = state.methodVersions.find(item => item.id === method.draftVersionId);
  $('#record-dialog-content').innerHTML = `<div class="dialog-content"><p class="label">METHOD LIBRARY · ${esc(method.status)}</p><h2>${esc(method.title)}</h2><p class="record-summary">${esc(method.purpose)}</p><div class="chips"><span class="chip">Owner ${esc(method.ownerId)}</span><span class="chip">${versions.filter(item => item.status === 'published').length} published version${versions.filter(item => item.status === 'published').length === 1 ? '' : 's'}</span><span class="chip">${executions.length} execution${executions.length === 1 ? '' : 's'}</span></div><div class="form-actions"><button class="primary-button" data-action="edit-method" data-id="${esc(method.id)}">Edit draft</button>${draft ? '<button class="secondary-button" data-action="publish-method" data-id="' + esc(method.id) + '">Publish draft</button>' : ''}${method.currentVersionId ? '<button class="icon-button" data-action="new-method-execution" data-id="' + esc(method.id) + '">Execute latest version</button>' : ''}${method.currentVersionId ? '<button class="text-button" data-action="clone-method" data-id="' + esc(method.id) + '">Create new draft from latest</button>' : ''}${method.status !== 'retired' ? '<button class="text-button" data-action="retire-method" data-id="' + esc(method.id) + '">Retire method</button>' : ''}</div><h3>VERSION HISTORY</h3>${versions.map(version => `<article class="record"><div class="record-top"><div><strong>${version.status === 'published' ? `Version ${version.version}` : 'Current draft'}</strong><span class="record-date">${formatDate(version.publishedAt || version.createdAt)}</span></div><span class="status ${version.status === 'published' ? 'verified' : 'unknown-stock'}">${version.status}</span></div><p>${esc(version.purpose)}</p><p class="muted">${version.steps.length} steps · ${version.measurements.length} measurement definitions · ${version.evidenceRequirements.length} evidence requirements</p>${version.status === 'published' ? `<button class="icon-button" data-action="new-method-execution-version" data-id="${esc(version.id)}">Execute version ${version.version}</button>` : ''}</article>`).join('') || '<p class="muted">No versions recorded.</p>'}<h3>EXECUTION HISTORY</h3>${executions.map(execution => `<article class="record"><div class="record-top"><strong>${esc(execution.status)}</strong><span class="record-date">${formatDate(execution.startedAt)}</span></div><p>Version ${esc(versions.find(item => item.id === execution.methodVersionId)?.version || '?')} · ${execution.measurements.length} measurements · ${execution.deviations.length} deviations</p><button class="icon-button" data-action="open-method-execution" data-id="${esc(execution.id)}">Open report</button></article>`).join('') || '<p class="muted">No executions yet.</p>'}</div>`;
  openDialog('record-dialog');
}

function showMethodExecutionForm(methodId, versionId) {
  const method = state.methods.find(item => item.id === methodId); const version = state.methodVersions.find(item => item.id === (versionId || method?.currentVersionId)); if (!method || !version || version.status !== 'published') return;
  $('#record-dialog-content').innerHTML = `<form id="method-execution-form" class="dialog-content" data-method-id="${esc(method.id)}" data-method-version-id="${esc(version.id)}"><p class="label">METHOD EXECUTION</p><h2>${esc(method.title)} · version ${version.version}</h2><p class="muted">Select an existing experiment or batch. The selected published version is stored on the execution and cannot change later.</p><div class="form-grid"><label>Experiment<select name="experimentId"><option value="">Not linked</option>${state.experiments.map(item => `<option value="${esc(item.id)}">${esc(item.experimentId)} · ${esc(item.title)}</option>`).join('')}</select></label><label>Physical batch<select name="batchId"><option value="">Not linked</option>${state.batches.map(item => `<option value="${esc(item.id)}">${esc(item.batchCode)}</option>`).join('')}</select></label><label>Start date/time<input name="startedAt" type="datetime-local" value="${esc(localDateTime())}" required></label></div><h3>DOCUMENTED PROCEDURE</h3><ol>${version.steps.map(step => `<li><strong>${esc(step.title)}</strong> <span class="muted">${esc(step.type)}${step.unit ? ` · ${esc(step.unit)}` : ''}</span><br>${esc(step.instruction || step.condition || step.expected || 'Follow the documented step and record the actual result in the execution report.')}</li>`).join('')}</ol><div class="form-actions"><button type="button" class="text-button" data-close="record-dialog">Cancel</button><button class="primary-button" type="submit">Start execution</button></div></form>`;
  openDialog('record-dialog');
}

function showMethodExecutionReport(executionId) {
  const report = methodExecutionReport(state, executionId); const { execution, version, method } = report;
  $('#record-dialog-content').innerHTML = `<div class="dialog-content"><p class="label">EXECUTION REPORT · ${esc(execution.status)}</p><h2>${esc(method.title)} · version ${version.version}</h2><p class="record-summary">Started ${formatDate(execution.startedAt)}${execution.completedAt ? ` · completed ${formatDate(execution.completedAt)}` : ''}</p><div class="chips"><span class="chip">Acceptance: ${esc(report.acceptance)}</span><span class="chip">${report.missingSteps.length} missing required steps</span><span class="chip">${report.missingMeasurements.length} missing measurements</span><span class="chip">${report.missingConditions.length} missing conditions</span><span class="chip">${execution.deviations.length} deviations</span></div><h3>STEP RECORDS</h3>${version.steps.map(step => { const result = execution.steps.find(item => item.stepId === step.id) || {}; return `<form class="method-step-form record" data-execution-id="${esc(execution.id)}" data-step-id="${esc(step.id)}"><div class="form-grid"><label>${esc(step.title)}<select name="status"><option value="not-started" ${result.status === 'not-started' ? 'selected' : ''}>Not started</option><option value="completed" ${result.status === 'completed' ? 'selected' : ''}>Completed</option><option value="skipped" ${result.status === 'skipped' ? 'selected' : ''}>Skipped</option></select></label><label>Step notes<textarea name="notes" rows="2">${esc(result.notes || '')}</textarea></label></div><button class="icon-button" type="submit">Save step record</button></form>`; }).join('')}<h3>MEASUREMENTS</h3>${execution.measurements.map(item => `<article class="record"><strong>${esc(item.name)}: ${esc(item.value)} ${esc(item.unit)}</strong><span class="status ${item.criterionResult === 'pass' ? 'verified' : item.criterionResult === 'fail' ? 'unknown-stock' : ''}">${esc(item.criterionResult)}</span><p class="muted">${esc(item.criterionReason)}</p></article>`).join('') || '<p class="muted">No observed measurements recorded.</p>'}<form id="method-measurement-form" class="record" data-execution-id="${esc(execution.id)}"><h4>Record measurement</h4><div class="form-grid"><label>Definition<select name="methodMeasurementId">${version.measurements.map(item => `<option value="${esc(item.id)}">${esc(item.name)} · ${esc(item.unit)}</option>`).join('')}</select></label><label>Value<input name="value" type="number" step="any" required></label><label>Unit<input name="unit" required></label><label>Equipment ID<input name="equipmentId" placeholder="Optional"></label></div><label>Condition<textarea name="condition" rows="2" placeholder="Sample/environment condition"></textarea></label><label>Notes<textarea name="notes" rows="2"></textarea></label><button class="secondary-button" type="submit">Save measurement</button></form><h3>CONDITIONS, OBSERVATIONS &amp; EVIDENCE</h3>${execution.conditions.map(item => `<article class="record"><strong>${esc(item.name)}</strong><p>${esc(item.value)} ${esc(item.unit || '')}</p></article>`).join('') || '<p class="muted">No observed conditions recorded.</p>'}<form id="method-condition-form" class="record" data-execution-id="${esc(execution.id)}"><h4>Record condition</h4><div class="form-grid"><label>Definition<select name="methodConditionId">${version.conditions.map(item => `<option value="${esc(item.id)}">${esc(item.name)} · expected ${esc(item.expected)}</option>`).join('')}</select></label><label>Observed value<input name="value" required></label><label>Unit<input name="unit"></label></div><label>Notes<textarea name="notes" rows="2"></textarea></label><button class="secondary-button" type="submit">Save condition</button></form>${execution.observations.map(item => `<article class="record"><strong>${esc(item.name)}</strong><p>${esc(item.value || 'Observation not recorded')}</p><span class="muted">${formatDate(item.observedAt)}</span></article>`).join('') || '<p class="muted">No observations recorded.</p>'}<form id="method-observation-form" class="record" data-execution-id="${esc(execution.id)}"><h4>Record observation</h4><div class="form-grid"><label>Name<input name="name" required></label><label>Observed value<input name="value"></label></div><label>Notes<textarea name="notes" rows="2"></textarea></label><button class="secondary-button" type="submit">Save observation</button></form>${(execution.evidence || []).map(item => `<article class="record"><strong>Evidence</strong><p>${esc(item.reference)}</p><span class="muted">${esc(item.notes || '')}</span></article>`).join('') || '<p class="muted">No evidence references recorded.</p>'}<form id="method-evidence-form" class="record" data-execution-id="${esc(execution.id)}"><h4>Record evidence reference</h4><div class="form-grid"><label>Requirement<select name="requirementId">${version.evidenceRequirements.map(item => `<option value="${esc(item.id)}">${esc(item.name)}</option>`).join('')}</select></label><label>Reference<input name="reference" required placeholder="Notebook, image, instrument export, or record ID"></label></div><label>Notes<textarea name="notes" rows="2"></textarea></label><button class="secondary-button" type="submit">Save evidence reference</button></form>${execution.deviations.map(item => `<article class="record"><strong>Deviation</strong><p>${esc(item.description)}</p><span class="muted">${esc(item.reason || 'Reason not recorded')}</span></article>`).join('')}<form id="method-deviation-form" class="record" data-execution-id="${esc(execution.id)}"><h4>Record deviation</h4><label>Description<textarea name="description" rows="2" required></textarea></label><label>Reason<textarea name="reason" rows="2"></textarea></label><button class="secondary-button" type="submit">Save deviation</button></form><div class="form-actions">${execution.status === 'in-progress' ? `<button class="primary-button" data-action="complete-method-execution" data-id="${esc(execution.id)}">Mark execution completed</button><button class="text-button" data-action="interrupt-method-execution" data-id="${esc(execution.id)}">Interrupt execution</button>` : ''}<button class="text-button" data-close="record-dialog">Close report</button></div>${report.missingSteps.length || report.missingMeasurements.length || report.missingConditions.length || report.missingObservations.length || report.missingEvidence.length ? `<div class="assumption-note"><strong>Incomplete evidence</strong><span>${[...report.missingSteps, ...report.missingMeasurements, ...report.missingConditions, ...report.missingObservations, ...report.missingEvidence].map(item => esc(item)).join(' · ')}</span></div>` : '<div class="assumption-note"><strong>No required items are missing</strong><span>This report records the execution only; it does not establish safety, stability, regulatory approval, or scientific validity.</span></div>'}</div>`;
  openDialog('record-dialog');
}

function renderAll() { $('#stat-journal').textContent = state.journalEntries.length; $('#stat-experiments').textContent = state.experiments.filter(item => item.status !== 'Archived').length; $('#stat-maturing').textContent = state.experiments.filter(item => item.status === 'Maturing').length; $('#stat-evaluations').textContent = state.evaluations.length; const banner = $('#recovery-banner'); if (banner) { banner.hidden = !storageLocked; $('#recovery-message').textContent = loadError || 'Saved data is unreadable.'; } renderJournal(); renderExperiments(); renderEvaluationJournal(); renderCoachControls(); try { renderMaterials(); renderEquipment(); renderPurchases(); renderBlindSessions(); renderMaturationPlans(); renderExperimentDesigns(); renderMethods(); } catch (error) { console.error(error); $('#material-list').innerHTML = `<div class="empty-state"><strong>Inventory could not render.</strong>${esc(error.message)}</div>`; } renderCompare(); companionApi?.render(); }

function journalFormValues(form) { const values = Object.fromEntries(new FormData(form)); return { title: values.title, observedAt: new Date(`${values.observedAt}T12:00:00`).toISOString(), experimentId: values.experimentId || undefined, medium: values.medium, evaluationTimeMinutes: values.evaluationTimeMinutes ? Number(values.evaluationTimeMinutes) : undefined, purpose: values.purpose, hypothesis: values.purpose, opening: values.opening, heart: values.heart, dryDown: values.dryDown, overall: values.dryDown, descriptors: tags(values.descriptors), tags: tags(values.tags), intensity: values.intensity ? Number(values.intensity) : undefined, projection: values.projection ? Number(values.projection) : undefined, personalNotes: values.personalNotes, attachmentRefs: [] }; }
function showJournalForm(entry = null) { const form = $('#journal-form'); form.reset(); form.dataset.editId = entry?.id || ''; form.elements.experimentId.innerHTML = '<option value="">Not linked</option>' + state.experiments.map(item => `<option value="${esc(item.id)}">${esc(item.experimentId)} · ${esc(item.title)}</option>`).join(''); form.elements.observedAt.value = entry?.observedAt?.slice(0, 10) || today(); if (entry) for (const key of ['title', 'medium', 'purpose', 'opening', 'heart', 'dryDown', 'personalNotes', 'experimentId']) if (entry[key] != null && form.elements[key]) form.elements[key].value = entry[key]; form.elements.descriptors.value = entry?.descriptors?.join(', ') || ''; form.elements.tags.value = entry?.tags?.join(', ') || ''; form.elements.evaluationTimeMinutes.value = entry?.evaluationTimeMinutes || ''; form.elements.intensity.value = entry?.intensity || ''; form.elements.projection.value = entry?.projection || ''; $('#journal-dialog h2').textContent = entry ? 'Edit journal entry' : 'New journal entry'; openDialog('journal-dialog'); }

function showLegacyExperimentDetail(id) { const experiment = getExperiment(id); const revisions = state.revisions.filter(item => experiment.formulaRevisionIds.includes(item.id)); const batches = state.batches.filter(item => experiment.batchIds.includes(item.id)); const evaluations = state.evaluations.filter(item => experiment.evaluationIds?.includes(item.id)); $('#record-dialog-content').innerHTML = `<div class="dialog-content"><p class="label">${esc(experiment.experimentId)} · ${esc(experiment.status)}</p><h2>${esc(experiment.title)}</h2><p class="record-summary">${esc(experiment.objective)}</p><div class="chips"><span class="chip">Created ${formatDate(experiment.createdAt)}</span><span class="chip">${revisions.length} formula revisions</span><span class="chip">${batches.length} batches</span><span class="chip">${evaluations.length} evaluations</span></div><div class="form-actions"><button class="primary-button" data-action="new-revision" data-id="${esc(id)}">＋ Formula revision</button><button class="icon-button" data-action="new-batch" data-id="${esc(id)}">Record batch</button><button class="icon-button" data-action="new-evaluation" data-id="${esc(id)}">Add evaluation</button></div><h3>REVISION HISTORY</h3>${revisions.map(revision => `<div class="record"><strong>Revision ${revision.revision}</strong><span class="record-date"> · ${formatDate(revision.createdAt)}</span><p class="record-summary">${esc(revision.notes || 'No notes')}</p><div class="chips">${(revision.ingredients || []).map(item => `<span class="chip">${esc(item.materialName || item.materialId)} · ${esc(item.quantity)} ${esc(item.unit)}</span>`).join('')}</div></div>`).join('') || '<p class="muted">No revisions yet.</p>'}<h3>BATCH HISTORY</h3>${batches.map(batch => { const summary = batchSummary(batch); return `<div class="record"><strong>${esc(batch.batchCode)}</strong><p class="record-summary">Actual ${summary.totalAmount} ${summary.unit} · active amount ${summary.totalActiveAmount} ${summary.unit}</p></div>`; }).join('') || '<p class="muted">No batches yet.</p>'}</div>`; openDialog('record-dialog'); }

function showRevisionForm(experimentId) { const experiment = getExperiment(experimentId); $('#record-dialog-content').innerHTML = `<form id="revision-form" class="dialog-content" data-experiment-id="${esc(experimentId)}"><p class="label">${esc(experiment.experimentId)} · PRESERVED HISTORY</p><h2>New formula revision</h2><p class="muted">Revision ${experiment.formulaRevisionIds.length + 1} will supersede the current revision without changing it.</p><label>Revision notes<textarea name="notes" rows="3" required placeholder="What changed and why?"></textarea></label><label>Ingredients<textarea name="ingredients" rows="5" required placeholder="Material name | quantity | unit | concentration | role&#10;Cedar accord | 2 | g | 100 | base"></textarea></label><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experimentId)}">Cancel</button><button class="primary-button">Save revision</button></div></form>`;
  openDialog("record-dialog");
}
function showLegacyBatchForm(experimentId) { const experiment = getExperiment(experimentId); const revisions = state.revisions.filter(item => experiment.formulaRevisionIds.includes(item.id)); $('#record-dialog-content').innerHTML = `<form id="batch-form" class="dialog-content" data-experiment-id="${esc(experimentId)}"><p class="label">ACTUAL ADDITIONS · TRACEABLE</p><h2>Record a batch</h2><label>Formula revision<select name="formulaRevisionId">${revisions.map(item => `<option value="${esc(item.id)}">Revision ${item.revision}</option>`).join('')}</select></label><div class="form-grid"><label>Planned quantity<input name="plannedAmount" type="number" min="0.0001" step="0.0001" required></label><label>Unit<select name="unit"><option>g</option><option>mL</option></select></label></div><label>Actual additions<textarea name="additions" rows="5" required placeholder="Material ID or name | lot ID | amount | unit | concentration&#10+material-seed-1 | lot-seed-1 | 2 | g | 100"></textarea></label><label>Procedure / maturation notes<textarea name="procedureNotes" rows="3"></textarea></label><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experimentId)}">Cancel</button><button class="primary-button">Save batch</button></div></form>`; }
function showEvaluationForm(experimentId) { const experiment = getExperiment(experimentId); const batches = state.batches.filter(item => experiment.batchIds.includes(item.id)); $('#record-dialog-content').innerHTML = `<form id="evaluation-form" class="dialog-content" data-experiment-id="${esc(experimentId)}"><p class="label">SENSORY EVALUATION</p><h2>Record an observation</h2><div class="form-grid"><label>Interval label<input name="intervalLabel" placeholder="e.g. 24 hours"></label><label>Medium<select name="medium"><option>Blotter</option><option>Skin</option><option>Other</option></select></label><label>Batch<select name="batchId">${batches.map(item => `<option value="${esc(item.id)}">${esc(item.batchCode)}</option>`).join('')}</select></label><label>Evaluation date<input name="evaluatedAt" type="date" value="${today()}"></label></div><label>Descriptors<input name="descriptors" placeholder="green, woody, soft"></label><label>Subjective notes<textarea name="subjectiveNotes" rows="3"></textarea></label><label>Measured results (optional; include method)<textarea name="measuredResults" rows="3"></textarea></label><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experimentId)}">Cancel</button><button class="primary-button">Save evaluation</button></div></form>`; }

function batchAdditionRow(index, values = {}) {
  const materials = state.materials.map(material => `<option value="${esc(material.id)}" ${material.id === values.materialId ? 'selected' : ''}>${esc(material.name)}</option>`).join('');
  const material = state.materials.find(item => item.id === (values.materialId || state.materials[0]?.id));
  const lots = (material?.lots || []).map(lot => `<option value="${esc(lot.id)}" ${lot.id === values.materialLotId ? 'selected' : ''}>${esc(lot.lotCode || lot.id)} · ${esc(lot.receivedUnit || stockStatus(state, lot.id).unit || '?')}</option>`).join('');
  return `<div class="batch-addition-row" data-addition-index="${index}"><div class="form-grid"><label>Material<select name="materialId" data-role="addition-material" required>${materials}</select></label><label>Physical lot<select name="materialLotId" data-role="addition-lot" required>${lots}</select></label><label>Actual quantity<input name="amount" type="number" min="0.0001" step="0.0001" value="${esc(values.amount ?? '')}" required></label><label>Unit<select name="unit"><option value="mg" ${values.unit === 'mg' ? 'selected' : ''}>mg</option><option value="g" ${values.unit === 'g' || !values.unit ? 'selected' : ''}>g</option><option value="kg" ${values.unit === 'kg' ? 'selected' : ''}>kg</option><option value="mL" ${values.unit === 'mL' ? 'selected' : ''}>mL</option><option value="L" ${values.unit === 'L' ? 'selected' : ''}>L</option></select></label><label>Receipt price<select name="purchaseLineItemId">${purchaseLineOptions(values.materialLotId, values.purchaseLineItemId)}</select></label><label>Concentration (%)<input name="concentration" type="number" min="0" max="100" step="0.01" value="${esc(values.concentration ?? 100)}"></label><label>Added at<input name="addedAt" type="datetime-local" value="${esc(values.addedAt || '')}"></label></div><button type="button" class="text-button" data-action="remove-batch-addition">Remove addition</button></div>`;
}

function renderBatchAdditionRows(form, rows) { $('#batch-additions').innerHTML = rows.map((values, index) => batchAdditionRow(index, values)).join(''); }

function showBatchForm(experimentId) {
  const experiment = getExperiment(experimentId); const revisions = state.revisions.filter(item => experiment.formulaRevisionIds.includes(item.id)); const revision = revisions.at(-1);
  const seedRows = (revision?.ingredients || []).map(ingredient => ({ materialId: ingredient.materialId, materialLotId: ingredient.lotId || state.materials.find(item => item.id === ingredient.materialId)?.lots?.[0]?.id, amount: ingredient.quantity, unit: ingredient.unit, concentration: ingredient.stockConcentration ?? 100 }));
  $('#record-dialog-content').innerHTML = `<form id="batch-form" class="dialog-content" data-experiment-id="${esc(experimentId)}"><p class="label">PHYSICAL BATCH · TRACEABLE</p><h2>Record what was actually mixed</h2><p class="muted"><strong>${esc(experiment.experimentId)} · ${esc(experiment.title)}</strong><br>Choose one exact formula revision. Planned quantities remain unchanged; each row below creates one lot-specific stock consumption.</p><div class="form-grid"><label>Formula revision<select name="formulaRevisionId" id="batch-form-revision">${revisions.map(item => `<option value="${esc(item.id)}" ${item.id === revision?.id ? 'selected' : ''}>Revision ${item.revision} · ${esc(item.notes || 'No notes')}</option>`).join('')}</select></label><label>Batch identifier<input name="batchCode" required placeholder="BATCH-004"></label><label>Planned batch size<input name="plannedAmount" type="number" min="0.0001" step="0.0001" required></label><label>Unit<select name="unit"><option>mg</option><option selected>g</option><option>kg</option><option>mL</option><option>L</option></select></label><label>Mixing date/time<input name="mixingDate" type="datetime-local" required></label></div><div class="section-heading"><div><p class="label">ACTUAL ADDITIONS</p><h3>One row per physical addition</h3></div><button type="button" class="secondary-button" data-action="add-batch-addition">＋ Add row</button></div><div id="batch-additions"></div><label>Procedure notes<textarea name="procedureNotes" rows="3" placeholder="Order of addition, temperature, mixing method…"></textarea></label><label>Relevant observations<textarea name="observations" rows="2" placeholder="Appearance, clarity, unexpected behavior…"></textarea></label><label>Deviations from plan<textarea name="deviations" rows="2" placeholder="Record deviations; do not edit the formula revision."></textarea></label><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experimentId)}">Cancel</button><button class="primary-button">Append physical batch</button></div></form>`;
  const form = $('#batch-form'); form.elements.plannedAmount.value = revision?.ingredients?.reduce((sum, item) => item.unit === (revision.ingredients[0]?.unit || 'g') ? sum + item.quantity : sum, 0) || ''; form.elements.mixingDate.value = new Date().toISOString().slice(0, 16); renderBatchAdditionRows(form, seedRows.length ? seedRows : [{}]);

  openDialog("record-dialog");
}

function showBatchDetail(batchId, experimentId) {
  const batch = state.batches.find(item => item.id === batchId); const experiment = getExperiment(experimentId || batch?.experimentId); if (!batch || !experiment) return;
  const revision = state.revisions.find(item => item.id === batch.formulaRevisionId); const comparison = compareBatchToPlan(state, batch.id); const summary = batchSummary(batch); const rowStatus = row => row.status === 'missing' ? 'Missing' : row.status === 'deviates' ? 'Deviation' : 'Matched';
  $('#record-dialog-content').innerHTML = `<div class="dialog-content"><p class="label">${esc(experiment.experimentId)} · PHYSICAL BATCH</p><h2>${esc(batch.batchCode)}</h2><p class="record-summary">Revision ${esc(revision?.revision || '?')} · mixed ${formatDate(batch.mixingDate)} · planned ${esc(batch.plannedAmount)} ${esc(batch.unit)} · actual ${esc(summary.totalAmount.toFixed(4))} ${esc(summary.unit)}</p><div class="chips"><span class="chip">${comparison.totalDifference >= 0 ? '+' : ''}${comparison.totalDifference.toFixed(4)} ${esc(comparison.unit)} vs formula ingredients</span><span class="chip">${batch.actualAdditions.length} actual additions</span><span class="chip">${batch.actualAdditions.filter(item => item.stockMovementId).length} linked movements</span></div><h3>PLANNED VS ACTUAL</h3><div class="table-wrap"><table><thead><tr><th>PLANNED MATERIAL</th><th>PLANNED</th><th>ACTUAL</th><th>DIFFERENCE</th><th>STATUS</th></tr></thead><tbody>${comparison.rows.map(row => `<tr><td>${esc(row.materialName)}${row.lotId ? `<br><small class="muted">Lot ${esc(lotMovementHistory(state, row.lotId)[0]?.materialLotId || row.lotId)}</small>` : ''}</td><td>${esc(row.amountInBatchUnit.toFixed(4))} ${esc(comparison.unit)}</td><td>${esc(row.actualAmount.toFixed(4))} ${esc(comparison.unit)}</td><td>${row.difference >= 0 ? '+' : ''}${esc(row.difference.toFixed(4))} ${esc(comparison.unit)}</td><td>${rowStatus(row)}</td></tr>`).join('')}${comparison.extraAdditions.map(addition => `<tr><td>${esc(addition.materialName)}<br><small class="muted">Extra · lot ${esc(addition.lotCode)}</small></td><td>—</td><td>${esc(addition.amountInBatchUnit.toFixed(4))} ${esc(comparison.unit)}</td><td>+${esc(addition.amountInBatchUnit.toFixed(4))} ${esc(comparison.unit)}</td><td>Extra</td></tr>`).join('')}</tbody></table></div><h3>ACTUAL LOT USE</h3><ul>${batch.actualAdditions.map(addition => { const material = state.materials.find(item => item.id === addition.materialId); const lot = material?.lots?.find(item => item.id === addition.materialLotId); const movement = state.stockMovements.find(item => item.id === addition.stockMovementId); return `<li>${esc(material?.name || addition.materialId)} · lot ${esc(lot?.lotCode || addition.materialLotId)} · ${esc(addition.amount)} ${esc(addition.unit)} · movement ${esc(movement?.id || addition.stockMovementId)}</li>`; }).join('')}</ul><h3>PROCESS RECORD</h3><p>${esc(batch.procedureNotes || 'No procedure notes recorded.')}</p><p>${esc(batch.observations || 'No relevant observations recorded.')}</p><p><strong>Deviations:</strong> ${esc(batch.deviations || 'None recorded.')}</p><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experiment.id)}">Back to experiment</button></div></div>`;
}

