       if (type === 'edit-method') showMethodForm(action.dataset.id);
       if (type === 'publish-method') { try { const next = publishMethod(state, action.dataset.id); if (persist(next)) { toast('Method version published'); showMethodDetail(action.dataset.id); } } catch (error) { toast(error.message); } }
       if (type === 'clone-method') { try { const next = clonePublishedMethodToDraft(state, action.dataset.id); if (persist(next)) { toast('New draft created from the published version'); showMethodDetail(action.dataset.id); } } catch (error) { toast(error.message); } }
       if (type === 'retire-method') { try { const next = retireMethod(state, action.dataset.id); if (persist(next)) { toast('Method retired; historical versions remain readable'); showMethodDetail(action.dataset.id); } } catch (error) { toast(error.message); } }
       if (type === 'new-method-execution') { const method = state.methods.find(item => item.id === action.dataset.id); showMethodExecutionForm(action.dataset.id, method?.currentVersionId); }
       if (type === 'new-method-execution-version') { const version = state.methodVersions.find(item => item.id === action.dataset.id); showMethodExecutionForm(version?.methodId, version?.id); }
       if (type === 'open-method-execution') showMethodExecutionReport(action.dataset.id);
       if (type === 'complete-method-execution') { try { const next = completeMethodExecution(state, action.dataset.id); if (persist(next)) { toast('Method execution marked completed'); showMethodExecutionReport(action.dataset.id); } } catch (error) { toast(error.message); } }
       if (type === 'interrupt-method-execution') { const reason = window.prompt('Why was this execution interrupted?'); if (reason) { try { const next = interruptMethodExecution(state, action.dataset.id, reason); if (persist(next)) { toast('Method execution interrupted'); showMethodExecutionReport(action.dataset.id); } } catch (error) { toast(error.message); } } }
      if (type === 'edit-design-run') showExperimentDesignRunForm(action.dataset.id);
      if (type === 'randomize-design') { try { const result = persistState(persistence, randomizeExperimentDesignRuns(state, action.dataset.id), { locked: storageLocked }); if (result.ok) { state = result.state; renderAll(); toast('Experiment execution order randomized and saved'); } else toast(result.error); } catch (error) { toast(error.message); } }
      if (type === 'new-maturation-observation') showMaturationObservationForm(action.dataset.planId, action.dataset.checkpointId);
      if (type === 'open-maturation-plan') { currentScreen = 'maturation'; renderMaturationPlans(); }
      if (type === 'add-maturation-checkpoint') { const rows = [...document.querySelectorAll('#maturation-checkpoints .maturation-checkpoint-row')].map(row => rowValues(row)); document.querySelector('#maturation-checkpoints').insertAdjacentHTML('beforeend', maturationCheckpointRow({}, rows.length)); }
      if (type === 'remove-maturation-checkpoint') { const rows = document.querySelectorAll('#maturation-checkpoints .maturation-checkpoint-row'); if (rows.length > 1) action.closest('.maturation-checkpoint-row').remove(); }
      if (type === 'add-maturation-measurement') document.querySelector('#maturation-measured-values').insertAdjacentHTML('beforeend', maturationMeasuredValueRow());
      if (type === 'remove-maturation-measurement') action.closest('.maturation-measured-row').remove();
     if (type === 'randomize-blind') { try { const result = persistState(persistence, randomizeBlindSession(state, action.dataset.id), { locked: storageLocked }); if (result.ok) { state = result.state; renderAll(); toast('Blind sample order randomized and saved'); } else toast(result.error); } catch (error) { toast(error.message); } }
     if (type === 'start-blind') { try { const result = persistState(persistence, startBlindSession(state, action.dataset.id), { locked: storageLocked }); if (result.ok) { state = result.state; renderAll(); toast('Evaluator view started'); } else toast(result.error); } catch (error) { toast(error.message); } }
     if (type === 'blind-observe') showBlindObservationForm(action.dataset.sessionId, action.dataset.sampleId);
     if (type === 'lock-blind') { try { const result = persistState(persistence, lockBlindSession(state, action.dataset.id), { locked: storageLocked }); if (result.ok) { state = result.state; renderAll(); toast('Blind observations locked'); } else toast(result.error); } catch (error) { toast(error.message); } }
     if (type === 'unblind-session') { try { const result = persistState(persistence, unblindSession(state, action.dataset.id), { locked: storageLocked }); if (result.ok) { state = result.state; renderAll(); toast('Session unblinded explicitly'); } else toast(result.error); } catch (error) { toast(error.message); } }
     if (type === 'add-purchase-line') { const rows = [...document.querySelectorAll('#purchase-lines .purchase-line-row')].map(row => rowValues(row)); rows.push({}); renderPurchaseLines(rows); }
     if (type === 'remove-purchase-line') { const rows = [...document.querySelectorAll('#purchase-lines .purchase-line-row')]; if (rows.length > 1) action.closest('.purchase-line-row').remove(); }
   if (type === 'new-verification') showVerificationForm(action.dataset.id);
   if (type === 'new-maintenance') showMaintenanceForm(action.dataset.id);
   if (type === 'new-measurement') showMeasurementForm(action.dataset.id);
