$('#import-file').addEventListener('change', async event => { const file = event.target.files?.[0]; if (!file) return; try { pendingBackup = parseBackup(await file.text()); const replacePreview = previewBackupImport(state, pendingBackup, { mode: 'replace', locked: storageLocked }); const detail = [`Schema ${pendingBackup.schemaVersion}${pendingBackup.migratedFromSchemaVersion ? ` → migrated to ${state.version}` : ''}`, `new records: ${replacePreview.imported}`, `changed IDs: ${replacePreview.changedRecords?.length || 0}`, `identical/preserved IDs: ${replacePreview.preserved?.length || 0}`, `records discarded by replace: ${replacePreview.discarded?.length || 0}`, `missing references: ${replacePreview.missingReferences?.length || 0}`]; $('#import-preview').textContent = `${detail.join(' · ')}. ${storageLocked ? 'The saved state is locked, so only validated Replace is available.' : 'Merge keeps current conflicting records and adds only missing IDs; Replace first saves the current state as a recoverable backup.'}`; $('#import-merge').disabled = storageLocked; $('#import-recovery').hidden = !recoveryAvailable; openDialog('import-dialog'); } catch (error) { toast(error.message); } finally { event.target.value = ''; } });
function finishImport(mode) { const result = applyBackupImport(persistence, pendingBackup, { mode, currentState: state, locked: storageLocked }); if (!result.ok) { if (pendingBackup && result.error !== 'No backup is pending.') toast(result.error); return; } state = result.state; storageLocked = result.locked; recoveryAvailable = recoveryAvailable || Boolean(result.recoveryCreated); $('#import-merge').disabled = storageLocked; $('#import-recovery').hidden = !recoveryAvailable; closeDialog('import-dialog'); pendingBackup = null; renderAll(); companionApi?.render(); toast(mode === 'merge' ? `Backup merged; ${result.imported} records added${result.conflicts.length ? `, ${result.conflicts.length} conflicts kept local` : ''}.` : `Backup restored${result.recoveryCreated ? '; previous local state is available for recovery' : ''}`); }
$('#import-merge').addEventListener('click', () => finishImport('merge'));
$('#import-replace').addEventListener('click', () => finishImport('replace'));
$('#import-recovery').addEventListener('click', () => { const result = restoreRecoveryBackup(persistence, { currentState: state, locked: storageLocked }); if (!result.ok) { toast(result.error); return; } state = result.state; storageLocked = result.locked; closeDialog('import-dialog'); renderAll(); companionApi?.render(); toast('Previous local state restored from the recovery backup'); });

async function readReceiptEvidence(form) {
  const file = form.elements.receiptFile.files?.[0];
  if (file) {
    if (file.size > 2 * 1024 * 1024) throw new Error('Receipt file must be no larger than 2 MB.');
    if (!/^(image\/|application\/pdf$|text\/plain$)/.test(file.type)) throw new Error('Receipt file type must be an image, PDF, or plain text file.');
    const dataUrl = await new Promise((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = () => reject(new Error('Receipt file could not be read.')); reader.readAsDataURL(file); });
    return { kind: 'file', reference: `local-file:${file.name}`, fileName: file.name, mediaType: file.type, sizeBytes: file.size, dataUrl };
  }
  const reference = form.elements.receiptReference.value.trim();
  return reference ? { kind: 'reference', reference } : form.existingEvidence;
}

function rowValues(row) { return Object.fromEntries([...row.querySelectorAll('input,select,textarea')].filter(input => input.name).map(input => [input.name, input.value])); }
function purchaseFormLines(form) { return [...form.querySelectorAll('.purchase-line-row')].map(row => rowValues(row)); }

