function appendBatchCosting(batchId) { const target = $('#record-dialog-content'); if (!target || target.querySelector('[data-batch-costing]')) return; const costing = calculateBatchCost(state, batchId); const totals = Object.entries(costing.totalsByCurrency).map(([currency, total]) => `${total.toFixed(2)} ${esc(currency)}`).join(' · ') || 'No costable additions'; const rows = costing.rows.map(row => row.costable ? `<tr><td>${esc(row.materialName)}</td><td>${esc(row.quantity)} ${esc(row.unit)}</td><td>${esc(row.unitCost.toFixed(6))} ${esc(row.currency)}/${esc(row.purchaseUnit)}</td><td>${esc(row.attributableCost.toFixed(2))} ${esc(row.currency)}</td><td>${esc(row.receiptNumber || row.purchaseId)}</td></tr>` : `<tr><td>${esc(row.materialName)}</td><td>${esc(row.quantity)} ${esc(row.unit)}</td><td colspan="3" class="unknown-stock">Uncosted: ${esc(row.message)}</td></tr>`).join(''); target.insertAdjacentHTML('beforeend', `<section data-batch-costing><h3>BATCH MATERIAL COST</h3><div class="chips"><span class="chip">Costable subtotal: ${totals}</span><span class="chip ${costing.complete ? '' : 'unknown-stock'}">${costing.complete ? 'Complete' : `${costing.uncosted.length} uncosted addition${costing.uncosted.length === 1 ? '' : 's'}`}</span></div><div class="table-wrap"><table><thead><tr><th>MATERIAL</th><th>ACTUAL ADDED</th><th>UNIT-COST BASIS</th><th>ATTRIBUTABLE COST</th><th>SOURCE RECEIPT</th></tr></thead><tbody>${rows}</tbody></table></div><p class="muted">Costing uses actual additions and the selected lot receipt price. A partial subtotal is not presented as a complete batch cost.</p></section>`); }
document.addEventListener('submit', event => {
  const form = event.target;
  if (!['method-form', 'method-execution-form', 'method-step-form', 'method-measurement-form', 'method-condition-form', 'method-observation-form', 'method-evidence-form', 'method-deviation-form'].includes(form.id || form.className)) return;
  event.preventDefault(); event.stopImmediatePropagation();
  try {
    if (form.id === 'method-form') { const input = methodDraftInput(form); const next = form.dataset.methodId ? updateMethodDraft(state, form.dataset.methodId, input) : createMethod(state, input); const methodId = form.dataset.methodId || next.methods[0]?.id; if (persist(next)) { closeDialog('record-dialog'); toast('Method draft saved'); renderMethods(); if (methodId) showMethodDetail(methodId); } return; }
    if (form.id === 'method-execution-form') { const values = Object.fromEntries(new FormData(form)); const next = startMethodExecution(state, { methodId: form.dataset.methodId, methodVersionId: form.dataset.methodVersionId, experimentId: values.experimentId || undefined, batchId: values.batchId || undefined, startedAt: values.startedAt ? new Date(values.startedAt).toISOString() : undefined }); const executionId = next.methodExecutions[0]?.id; if (persist(next)) { toast('Method execution started'); showMethodExecutionReport(executionId); } return; }
    if (form.id === 'method-step-form') { const values = Object.fromEntries(new FormData(form)); const next = recordMethodExecutionStep(state, form.dataset.executionId, form.dataset.stepId, values); if (persist(next)) { toast('Step record saved'); showMethodExecutionReport(form.dataset.executionId); } return; }
    if (form.id === 'method-measurement-form') { const values = Object.fromEntries(new FormData(form)); const next = recordMethodMeasurement(state, form.dataset.executionId, { ...values, value: Number(values.value), observedAt: new Date().toISOString() }); if (persist(next)) { toast('Measurement recorded'); showMethodExecutionReport(form.dataset.executionId); } return; }
    if (form.id === 'method-condition-form') { const values = Object.fromEntries(new FormData(form)); const next = recordMethodCondition(state, form.dataset.executionId, { ...values, observedAt: new Date().toISOString() }); if (persist(next)) { toast('Condition recorded'); showMethodExecutionReport(form.dataset.executionId); } return; }
    if (form.id === 'method-observation-form') { const values = Object.fromEntries(new FormData(form)); const next = recordMethodObservation(state, form.dataset.executionId, { ...values, observedAt: new Date().toISOString() }); if (persist(next)) { toast('Observation recorded'); showMethodExecutionReport(form.dataset.executionId); } return; }
    if (form.id === 'method-evidence-form') { const values = Object.fromEntries(new FormData(form)); const next = recordMethodEvidence(state, form.dataset.executionId, { ...values, recordedAt: new Date().toISOString() }); if (persist(next)) { toast('Evidence reference recorded'); showMethodExecutionReport(form.dataset.executionId); } return; }
    if (form.id === 'method-deviation-form') { const values = Object.fromEntries(new FormData(form)); const next = recordMethodDeviation(state, form.dataset.executionId, { ...values, recordedAt: new Date().toISOString() }); if (persist(next)) { toast('Deviation recorded'); showMethodExecutionReport(form.dataset.executionId); } }
  } catch (error) { toast(error.message); }
}, true);
